import 'package:flutter/material';

class FlutterCounter extends StatefulWidget {
  @override
  _FlutterCounterState createState() => _FlutterCounterState();
}

class _FlutterCounterState extends State<FlutterCounter> {
  int _counter = 0;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        IconButton(
          icon: Icon(Icons.remove),
          onPressed: () => setState(() => _counter--),
        ),
        Text('$_counter', style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),
        IconButton(
          icon: Icon(Icons.add),
          onPressed: () => setState(() => _counter++),
        ),
      ],
    );
  }
}
